"use client"

import React from 'react';
import { PlayerContainerProps } from '../types/player';
import styles from './PlayerContainer.module.css';

export const PlayerContainer: React.FC<PlayerContainerProps> = ({
  videoRef,
  youtubeContainerRef,
  vimeoContainerRef,
  playerState,
  playerControls,
  mp4,
  webm,
  captions,
  description,
  chapters,
  controlsType = 'minimal',
  onFullPlayerClick
}) => {
  


  const handleContainerClick = () => {
    if (!playerState.isPlaying) {
      playerControls.handlePlay();
      playerState.setControlsVisible(true);
    }
  };

  const handleMouseMove = () => {
    playerState.setControlsVisible(true);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div 
      className={`${styles.container} ${
        !playerState.isPlaying ? styles.containerClickable : styles.containerDefault
      }`}
      onClick={handleContainerClick}
      onMouseMove={handleMouseMove}
    >
      {/* Loading Overlay */}
      {playerState.isLoading && (
        <div className={styles.loadingOverlay}>
          <div>Lädt...</div>
        </div>
      )}

      {/* Poster Overlay */}
      {!playerState.isPlaying && !playerState.isLoading && (
        <div className={styles.posterOverlay}>
          {playerState.poster && (
            <img src={playerState.poster} alt=" " className={styles.posterImage} />
          )}

          <div className={styles.playButton}>
            ▶️
          </div>
        </div>
      )}

      {/* Video Element */}
      {(playerState.playerType === 'video' || playerState.playerType === 'btag') && playerState.videoSrc && (
        <video
          ref={videoRef}
          src={playerState.videoSrc}
          className={styles.videoElement}
          controls={false}
          playsInline
          autoPlay={false}
          muted={playerState.isMuted}
        >
          {controlsType === 'full' && captions && (
            <track kind="subtitles" src={captions} srcLang="de" label="Deutsche Untertitel" default />
          )}
          {controlsType === 'full' && description && (
            <track kind="descriptions" src={description} srcLang="de" label="Audiodeskription" />
          )}
          {controlsType === 'full' && chapters && (
            <track kind="chapters" src={chapters} srcLang="de" label="Kapitel" />
          )}
        </video>
      )}

      {/* YouTube Container */}
      {playerState.playerType === 'youtube' && (
        <div ref={youtubeContainerRef} className={styles.youtubeContainer} />
      )}

      {/* Vimeo Container */}
      {playerState.playerType === 'vimeo' && (
        <div ref={vimeoContainerRef} className={styles.vimeoContainer} />
      )}

      {/* Controls Overlay */}
      {(playerState.controlsVisible || !playerState.isPlaying) && (
        <div className={styles.controlBar} aria-label="Player-Steuerung">
          
          {/* FULL PLAYER - Progress Bar + 2 Reihen Controls */}
          {controlsType === 'full' && (
            <>
              {/* Progress Bar */}
              <div className={styles.progressBar}>
                <span className={styles.timeDisplay}>
                  {formatTime(playerState.currentTime)}
                </span>
                <input
                  type="range"
                  min={0}
                  max={playerState.duration || 1}
                  step={0.01}
                  value={playerState.currentTime}
                  onChange={e => playerControls.handleSeek(Number(e.target.value))}
                  aria-label="Fortschritt"
                  className={styles.progressSlider}
                />
                <span className={styles.timeDisplay}>
                  {formatTime(playerState.duration)}
                </span>
              </div>

              {/* First Row Controls */}
              <div className={styles.controlsRow}>
                <div className={styles.leftControls}>
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      playerState.isPlaying ? playerControls.handlePause() : playerControls.handlePlay();
                    }}
                    className={`${styles.controlButton} ${styles.playPauseButton}`}
                    aria-label={playerState.isPlaying ? 'Pausieren' : 'Abspielen'}
                  >
                    {playerState.isPlaying ? '⏸️' : '▶️'}
                  </button>

                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      playerControls.handleMuteToggle();
                    }}
                    className={styles.controlButton}
                    aria-label={playerState.isMuted ? 'Ton an' : 'Stumm'}
                  >
                    {playerState.isMuted ? '🔇' : '🔊'}
                  </button>

                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      playerControls.handleSeek(playerState.currentTime - 10);
                    }}
                    className={styles.controlButton}
                    aria-label="10 Sekunden zurück"
                  >
                    ⏪
                  </button>

                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      playerControls.handleSeek(playerState.currentTime + 10);
                    }}
                    className={styles.controlButton}
                    aria-label="10 Sekunden vor"
                  >
                    ⏩
                  </button>
                </div>

                <div className={styles.rightControls}>
                  {playerState.isPiPSupported && (
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        playerControls.handlePiP();
                      }}
                      className={styles.controlButton}
                      aria-label="Bild-in-Bild"
                    >
                      📺
                    </button>
                  )}

                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      playerControls.handleFullscreen();
                    }}
                    className={styles.controlButton}
                    aria-label="Vollbild"
                  >
                    ⛶
                  </button>
                </div>
              </div>

              {/* Second Row Controls */}
              <div className={styles.controlsRow}>
                <div className={styles.leftControls}>
                  <button className={styles.controlButton} aria-label="Qualität">
                    🎥
                  </button>

                  <button className={styles.controlButton} aria-label="Einstellungen">
                    ⚙️
                  </button>

                  {captions && (
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        playerState.setShowCC(!playerState.showCC);
                      }}
                      className={styles.controlButton}
                      aria-label="Untertitel"
                    >
                      CC
                    </button>
                  )}
                </div>
              </div>
            </>
          )}

          {/* MINIMAL PLAYER - Nur eine Reihe */}
          {controlsType === 'minimal' && (
            <div className={styles.controls}>
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  playerState.isPlaying ? playerControls.handlePause() : playerControls.handlePlay();
                }}
                className={`${styles.controlButton} ${styles.playPauseButton}`}
                aria-label={playerState.isPlaying ? 'Pausieren' : 'Abspielen'}
              >
                {playerState.isPlaying ? '⏸️' : '▶️'}
              </button>

              <button
                onClick={(e) => {
                  e.stopPropagation();
                  playerControls.handleMuteToggle();
                }}
                className={styles.controlButton}
                aria-label={playerState.isMuted ? 'Ton an' : 'Stumm'}
              >
                {playerState.isMuted ? '🔇' : '🔊'}
              </button>

              <div className={styles.spacer} />

              <button
                onClick={(e) => {
                  e.stopPropagation();
                  onFullPlayerClick?.();
                }}
                className={styles.controlButton}
                aria-label="Vollständiger Player"
              >
                🔗
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
};